CREATE OR REPLACE FUNCTION private.kinto_local_independent_amount_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
  v_old_details jsonb;
  v_new_details jsonb;
  v_projection jsonb;
BEGIN
  -- Avoid changing the global/legacy order pricing workflow.
  v_old_details := private.v94_jsonb_object(to_jsonb(OLD.details));
  IF coalesce(v_old_details->>'checkout_contract', '') <> 'independent_vendor_orders' THEN
    RETURN NEW;
  END IF;

  IF NEW.total_price IS NOT DISTINCT FROM OLD.total_price
     AND NEW.currency IS NOT DISTINCT FROM OLD.currency THEN
    RETURN NEW;
  END IF;

  -- Order currency is fixed by the checkout's trusted store calculation.
  IF NEW.currency IS DISTINCT FROM OLD.currency THEN
    RAISE EXCEPTION 'KINTO_LOCAL_ORDER_CURRENCY_LOCKED' USING ERRCODE='42501';
  END IF;

  -- Preserve the existing customer invoice/stock correction (V58/V59).
  -- Never allow a free-form price update, even when the invoice GUC is present.
  IF current_setting('kinto.invoice_adjustment_v58', true) = OLD.id::text
     AND OLD.status = ANY(ARRAY[
       'بانتظار موافقة العميل',
       'بانتظار موافقة الزبون',
       'بانتظار التسعير',
       'تم التسعير / بانتظار موافقة العميل'
     ])
     AND NEW.status IS NOT DISTINCT FROM OLD.status
     AND coalesce(v_old_details->>'bundle_stock_lifecycle_state','') <> 'deducted'
  THEN
    v_projection := private.invoice_stock_projection_v59(OLD);
    v_new_details := private.v94_jsonb_object(to_jsonb(NEW.details));
    IF v_projection->>'changed' = 'true'
       AND NEW.total_price IS NOT DISTINCT FROM (v_projection->>'total_price')::numeric
       AND v_new_details = v_projection->'details'
    THEN
      RETURN NEW;
    END IF;
  END IF;

  RAISE EXCEPTION 'KINTO_LOCAL_ORDER_AMOUNT_LOCKED' USING ERRCODE='42501';
END;
$function$

CREATE OR REPLACE FUNCTION private.kinto_paid_transition_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.status = 'تم التسديد') THEN
    RAISE EXCEPTION 'KINTO_PAYMENT_INSERT_DENIED' USING ERRCODE='42501';
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'تم التسديد' THEN
    IF NOT EXISTS (
      SELECT 1 FROM private.kinto_paid_transition_permits_v1 p
      WHERE p.transaction_id = txid_current() AND p.order_id = NEW.id
    ) THEN
      RAISE EXCEPTION 'KINTO_PAYMENT_APPROVAL_REQUIRED' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.kinto_paid_marker_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'pg_temp'
AS $function$
DECLARE
  old_json jsonb;
  new_json jsonb;
BEGIN
  IF NEW.details IS DISTINCT FROM OLD.details THEN
    old_json := coalesce(nullif(OLD.details, '')::jsonb, '{}'::jsonb);
    new_json := coalesce(nullif(NEW.details, '')::jsonb, '{}'::jsonb);
    -- Stock lifecycle evidence may be written by existing server-side triggers.
    -- Require the one-transaction approval permit when the marker enters deducted.
    IF old_json->>'bundle_stock_lifecycle_state' IS DISTINCT FROM 'deducted'
       AND new_json->>'bundle_stock_lifecycle_state' = 'deducted'
       AND NOT EXISTS (
         SELECT 1 FROM private.kinto_paid_transition_permits_v1 p
         WHERE p.transaction_id = txid_current() AND p.order_id = NEW.id
       ) THEN
      RAISE EXCEPTION 'KINTO_PAYMENT_MARKER_FORGERY_DENIED' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

